#!/usr/bin/env python3
# WARNING: This file is autogenerated - changes will be overwritten when regenerated by https://github.com/pulumi/ci-mgmt
"""Runs on every sandbox start, for whatever this session needs to be true now.

Sibling of setup.py, which bakes the image; this reconciles the running
session against the checkout it is actually on. Only image builds skip it.

Dispatches to .openinspect/start.d/*.py then .openinspect/start.local.py.
"""

import logging
import os
import subprocess
import sys
import time
from contextlib import contextmanager
from pathlib import Path


log = logging.getLogger("start")
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(phase)s] %(message)s",
    datefmt="%H:%M:%S",
    stream=sys.stdout,
)

_log_factory = logging.getLogRecordFactory()
_current_phase = "start"


def _record_factory(*args, **kwargs):
    record = _log_factory(*args, **kwargs)
    record.phase = _current_phase
    return record


logging.setLogRecordFactory(_record_factory)


@contextmanager
def phase(name: str, description: str = ""):
    global _current_phase
    prev = _current_phase
    _current_phase = name
    label = description or name
    log.info("Starting: %s", label)
    t0 = time.monotonic()
    try:
        yield
    except Exception:
        log.error("FAILED after %.1fs: %s", time.monotonic() - t0, label)
        raise
    else:
        log.info("Done in %.1fs: %s", time.monotonic() - t0, label)
    finally:
        _current_phase = prev


# Resolved once, here, and exported for every hook this script runs, so no hook
# has to count directories up from its own location. The sandbox runs this with
# the checkout as the working directory.
REPO_ROOT = Path.cwd()
OPENINSPECT_ROOT = REPO_ROOT / ".openinspect"
if not OPENINSPECT_ROOT.is_dir():
    # Without this the script dispatches nothing and still exits 0, which reads
    # as "no hooks configured" rather than "run from the wrong directory".
    sys.exit(f"run this from the repository root; {OPENINSPECT_ROOT} does not exist")
os.environ["REPO_ROOT"] = str(REPO_ROOT)
os.environ["OPENINSPECT_ROOT"] = str(OPENINSPECT_ROOT)
# Hooks import sibling modules by path; without this CPython litters the
# checkout with __pycache__, which the generated .gitignore does not cover.
os.environ["PYTHONDONTWRITEBYTECODE"] = "1"

# setup.py installs mise and so leaves its shims on PATH for the hooks it runs.
# Nothing installs mise here, so put them there directly - otherwise a hook that
# works in setup.d fails with command-not-found when copied to start.d.
_shims = Path(
    os.environ.get("MISE_DATA_DIR")
    or Path(os.environ.get("XDG_DATA_HOME") or Path.home() / ".local" / "share") / "mise"
) / "shims"
if _shims.is_dir() and str(_shims) not in os.environ.get("PATH", "").split(os.pathsep):
    os.environ["PATH"] = f"{_shims}{os.pathsep}{os.environ.get('PATH', '')}"


def run_hook(path: Path):
    log.info("$ %s %s", sys.executable, path)
    subprocess.run([sys.executable, str(path)], check=True, cwd=REPO_ROOT)


def run_start_hooks():
    """Run every start hook in order.

    Failures propagate: the sandbox treats a failed start hook as fatal to the
    session, and that policy belongs to the hook that has an opinion about it,
    not to this runner.
    """
    hooks_dir = OPENINSPECT_ROOT / "start.d"
    if hooks_dir.exists():
        for hook in sorted(hooks_dir.glob("*.py")):
            with phase("hook", f"Run {hook.relative_to(REPO_ROOT)}"):
                run_hook(hook)

    local_hook = OPENINSPECT_ROOT / "start.local.py"
    if local_hook.exists():
        with phase("hook", f"Run {local_hook.relative_to(REPO_ROOT)}"):
            run_hook(local_hook)


if __name__ == "__main__":
    t_total = time.monotonic()
    log.info("=== Sandbox start starting ===")

    run_start_hooks()

    elapsed_total = time.monotonic() - t_total
    log.info(
        "=== Sandbox start complete in %dm%ds ===",
        int(elapsed_total // 60),
        int(elapsed_total % 60),
    )
